using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class TimelineEditorOperations
{
    public void delete_selected(Control owner){Canvas(owner).Call("cancel_drag");_timeline.delete_selected(Model(owner));Canvas(owner).GrabFocus();}
    public void unparent_selected(Control owner){Canvas(owner).Call("cancel_drag");var ids=new GArray();foreach(var value in _timeline.selected_actors(Model(owner)))ids.Add(value.As<Resource>().Get("id"));_timeline.unparent_many(Model(owner),ids);Canvas(owner).GrabFocus();}
    public void parent_selected(Control owner){var model=Model(owner);var parent=_timeline.selected_actor(model);if(parent==null||model.Get("selected_ids").AsGodotArray().Count<2)return;var ids=new GArray();foreach(var value in _timeline.selected_actors(model)){var actor=value.As<Resource>();if(actor.Get("id").AsString()!=parent.Get("id").AsString())ids.Add(actor.Get("id"));}_timeline.parent_many(model,ids,parent.Get("id").AsString());Canvas(owner).GrabFocus();}
    public Godot.Collections.Array<Settings> capture_selected_snapshots(Control owner){var model=Model(owner);var snapshots=new Godot.Collections.Array<Settings>();foreach(var value in model.Get("selected_ids").AsGodotArray()){int index=_timeline.index_of(model,value.AsString());if(index<0)continue;var actor=Actors(owner)[index].As<Resource>();var clip=Clips(owner)[index].As<Resource>();snapshots.Add(new Settings{["actor"]=_data.copy_actor(actor),["source_id"]=actor.Get("id"),["source_parent"]=actor.Get("parent_id"),["start"]=clip.Get("start_time"),["duration"]=clip.Get("duration"),["offset"]=clip.Get("source_offset"),["speed"]=clip.Get("playback_speed"),["layer"]=clip.Get("layer")});}return snapshots;}
    public void copy_selected(Control owner){owner.Set("_actor_clipboard",capture_selected_snapshots(owner));Canvas(owner).GrabFocus();owner.Call("_update_idle_hint");}
    public void duplicate_selected(Control owner){var snapshots=capture_selected_snapshots(owner);if(snapshots.Count==0)return;double start=double.PositiveInfinity;int layer=int.MaxValue;foreach(var snapshot in snapshots){start=Math.Min(start,snapshot["start"].AsDouble());layer=Math.Min(layer,snapshot["layer"].AsInt32());}_timeline.paste_snapshots(Model(owner),Variant.From(snapshots).AsGodotArray(),start,layer,new GArray(),"Duplicate Actors",true);Canvas(owner).GrabFocus();}
    public void paste_copied(Control owner,bool asChildren,double time,int layer){var copied=owner.Get("_actor_clipboard").AsGodotArray();if(copied.Count==0)return;var parents=new GArray();if(asChildren)foreach(var value in _timeline.selected_actors(Model(owner)))parents.Add(value.As<Resource>().Get("id"));_timeline.paste_snapshots(Model(owner),copied,time,layer,parents,"Paste Actors",false);Canvas(owner).GrabFocus();}
    public Settings capture_clip_states(Control owner){var states=new Settings();var model=Model(owner);foreach(string id in _timeline.linked_clip_ids(model,model.Get("selected_ids").AsGodotArray())){int index=_timeline.index_of(model,id);if(index<0)continue;var clip=Clips(owner)[index].As<Resource>();states[id]=new Settings{["start"]=clip.Get("start_time"),["duration"]=clip.Get("duration"),["layer"]=clip.Get("layer"),["offset"]=clip.Get("source_offset")};}return states;}
    public Settings timing_states(Control owner,double value,string kind,Settings originals){string primaryId=Model(owner).Get("selected_id").AsString();if(!originals.TryGetValue(primaryId,out var entry))return new Settings();var primary=entry.AsGodotDictionary();var result=originals.Duplicate(true);double delta=value-primary["start"].AsDouble()-(kind=="start"?0:primary["duration"].AsDouble());foreach(var id in result.Keys){var item=result[id].AsGodotDictionary();item[kind=="start"?"start":"duration"]=originals[id].AsGodotDictionary()[kind=="start"?"start":"duration"].AsDouble()+delta;}return result;}
    public void set_keyframe_view(Control owner,bool enabled){Canvas(owner).Call("cancel_drag");owner.Get("property_overlay").As<Control>().Call("cancel_drag");var editor=owner.Get("keyframe_editor").As<Control>();if(!enabled)editor.Call("cancel_interaction");owner.Get("keyframes_button").As<Button>().SetPressedNoSignal(enabled);owner.Get("actor_view").As<Control>().Visible=!enabled;owner.Get("keyframe_view").As<Control>().Visible=enabled;owner.Get("breadcrumb_panel").As<Control>().Visible=!enabled;if(enabled)editor.Call("refresh");}
}
